CREATE OR REPLACE FUNCTION public.aprovar_pix_assistido(p_order_id uuid, p_operator_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_order public.commercial_orders%rowtype;
begin
  if p_operator_id is null then raise exception 'operador obrigatorio'; end if;
  select * into v_order from public.commercial_orders
    where id = p_order_id and payment_method = 'direct_pix' for update;
  if not found then raise exception 'pedido nao encontrado'; end if;
  if v_order.status = 'payment_approved' then return true; end if;
  if v_order.status <> 'proof_received' or v_order.business_id is null
      or v_order.proof_reference is null then
    raise exception 'comprovante e negocio obrigatorios';
  end if;
  update public.commercial_orders set status = 'payment_approved',
    payment_approved_at = now(), payment_approved_by = p_operator_id,
    updated_at = now() where id = p_order_id;
  insert into public.commercial_events(order_id, source, external_event_id,
    event_type, actor_profile_id)
    values (p_order_id, 'operator', 'approve:' || p_order_id::text,
      'pix_aprovado_por_operador', p_operator_id);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_conta_contratada(p_business_id uuid, p_connection_id uuid, p_external_id text, p_name text, p_currency text, p_page_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_account_id uuid;
  v_unit_id uuid;
  v_created_at timestamptz;
  v_legacy_at timestamptz;
  v_has_order boolean;
begin
  if p_business_id is null or p_connection_id is null
      or p_external_id is null or length(btrim(p_external_id)) < 3
      or length(p_external_id) > 100
      or p_page_id is null or length(btrim(p_page_id)) < 2
      or length(p_page_id) > 100 then
    raise exception 'conta ou pagina invalida';
  end if;

  select created_at into v_created_at from public.businesses
    where id = p_business_id for update;
  if not found then raise exception 'negocio nao encontrado'; end if;
  if not exists (select 1 from public.meta_connections
      where id = p_connection_id and business_id = p_business_id) then
    raise exception 'conexao nao pertence ao negocio';
  end if;

  select exists (select 1 from public.commercial_orders
    where business_id = p_business_id and status <> 'cancelled')
    into v_has_order;

  if v_has_order then
    select id into v_account_id from public.ad_accounts
      where business_id = p_business_id and external_id = btrim(p_external_id);

    if not exists (select 1 from public.commercial_order_units u
        join public.commercial_orders o on o.id = u.order_id
        where o.business_id = p_business_id and o.status = 'payment_approved'
          and u.ad_account_id = v_account_id) then
      select u.id into v_unit_id from public.commercial_order_units u
        join public.commercial_orders o on o.id = u.order_id
        where o.business_id = p_business_id and o.status = 'payment_approved'
          and u.ad_account_id is null
        order by o.created_at, u.ordinal limit 1 for update of u;
      if v_unit_id is null then
        if exists (select 1 from public.commercial_orders
            where business_id = p_business_id
              and status in ('awaiting_payment', 'proof_received')) then
          raise exception 'pedido ainda nao aprovado';
        end if;
        raise exception 'sem unidade contratada disponivel';
      end if;
    end if;
  else
    select min(granted_at) into v_legacy_at from public.webapp_legacy_access;
    if v_legacy_at is null or v_created_at > v_legacy_at then
      raise exception 'negocio novo sem pedido aprovado';
    end if;
  end if;

  insert into public.ad_accounts(
    business_id, meta_connection_id, external_id, name, currency,
    ownership, status, is_active
  ) values (
    p_business_id, p_connection_id, btrim(p_external_id),
    coalesce(nullif(btrim(p_name), ''), btrim(p_external_id)),
    nullif(btrim(p_currency), ''), 'cliente', 'ok', true
  ) on conflict (business_id, external_id) do update set
    meta_connection_id = excluded.meta_connection_id,
    name = excluded.name,
    currency = excluded.currency,
    ownership = 'cliente', status = 'ok', is_active = true
  returning id into v_account_id;

  if v_unit_id is not null then
    update public.commercial_order_units set ad_account_id = v_account_id
      where id = v_unit_id;
  end if;
  update public.meta_connections set meta_page_id = btrim(p_page_id)
    where id = p_connection_id and business_id = p_business_id;
  return v_account_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_pedido_pix_assistido(p_ref text, p_email text, p_legal_name text, p_cnpj text, p_unit_count integer, p_billing_period text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_email text := lower(btrim(p_email));
  v_legal_name text := btrim(p_legal_name);
  v_existing public.commercial_orders%rowtype;
  v_business_id uuid;
  v_order_id uuid;
  v_total integer;
begin
  if p_ref is null or p_ref !~ '^[0-9a-f-]{36}$' then
    raise exception 'referencia invalida';
  end if;
  if v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
      or length(v_email) > 254 then
    raise exception 'email invalido';
  end if;
  if v_legal_name is null or length(v_legal_name) < 2 or length(v_legal_name) > 200
      or p_cnpj is null or p_cnpj !~ '^[0-9]{14}$'
      or p_unit_count is null or p_unit_count not between 1 and 100
      or p_billing_period not in ('monthly', 'annual_upfront') then
    raise exception 'dados do pedido invalidos';
  end if;

  select * into v_existing from public.commercial_orders where external_ref = p_ref;
  if found then
    if v_existing.buyer_email = v_email and v_existing.legal_name = v_legal_name
        and v_existing.cnpj = p_cnpj and v_existing.unit_count = p_unit_count
        and v_existing.billing_period = p_billing_period
        and v_existing.payment_method = 'direct_pix' then
      return v_existing.id;
    end if;
    raise exception 'referencia ja utilizada';
  end if;

  -- Uma compra adicional do mesmo comprador/CNPJ usa o negócio existente.
  select business_id into v_business_id from public.commercial_orders
    where buyer_email = v_email and cnpj = p_cnpj and business_id is not null
      and status = 'payment_approved'
    order by created_at desc limit 1;
  if v_business_id is null then
    insert into public.businesses(name, claim_email)
      values (v_legal_name, v_email) returning id into v_business_id;
  end if;

  v_total := p_unit_count * case p_billing_period
    when 'monthly' then 50000 else 528000 end;
  insert into public.commercial_orders(
    external_ref, buyer_email, business_id, legal_name, cnpj,
    declares_cnpj, sells_by_whatsapp, origin, payment_method,
    billing_period, unit_price_cents, discount_percent, unit_count,
    total_cents, status
  ) values (
    p_ref, v_email, v_business_id, v_legal_name, p_cnpj,
    true, true, 'assisted', 'direct_pix', p_billing_period,
    50000, case p_billing_period when 'monthly' then 0 else 12 end,
    p_unit_count, v_total, 'awaiting_payment'
  ) returning id into v_order_id;

  insert into public.commercial_order_units(order_id, ordinal)
    select v_order_id, generate_series(1, p_unit_count);
  return v_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
